"""Keep the expanded pipeline in an English, text-and-code notebook."""
from pathlib import Path
import nbformat as nbf

BASE = Path(__file__).resolve().parent
notebook = nbf.v4.new_notebook()
notebook.metadata.kernelspec = {"display_name": "EcoSort Local (Python 3.12 / Metal)", "name": "ecosort-local", "language": "python"}
sections = [
    ("# EcoSort AI - Expanded Local Training\n\nThe public Garbage265 collection is combined with the original selected 20,000 images. Actual counts come from source indexes and image audits, not the advertised count. All original files and historical results remain separate.\n\n## 1. Project and environment\n\nConfirm the working folder and the native Apple Silicon GPU. This notebook uses the project virtual environment.", "from pathlib import Path\nimport json\nimport pandas as pd\nimport tensorflow as tf\nPROJECT = Path.cwd()\nassert (PROJECT / 'prepare_expanded.py').exists()\nprint(tf.config.list_physical_devices('GPU'))"),
    ("## 2. Download and verify the new source archives\n\nThe downloader resumes completed ranges and verifies both complete archives against the source repository SHA-256 values. The original publisher is tany0699 on ModelScope; files are retrieved from the fritz1024 public mirror. This collection contains Chinese item names, not City of Sydney disposal decisions.", "%run download_expanded.py"),
    ("## 3. Restore required RealWaste originals\n\nRestore images referenced by the old manifest from the authors' repository, verifying every image against its saved SHA-256. Other old source archives already exist under data/.", "%run restore_realwaste.py"),
    ("## 4. Audit, map categories, deduplicate and split\n\nDecode every candidate, reject small or corrupt images, retain source fine labels, group exact and perceptual duplicates and related source names, exclude conflicting label groups, and create approximately 80/10/10 group-separated partitions. No generated augmentation is counted as a new source image. Near-duplicate detection is heuristic.", "%run prepare_expanded.py"),
    ("## 5. Inspect actual data coverage\n\nReview class counts and the saved contact sheet before training. Ambiguous material labels are represented as mixed items rather than being silently relabelled as plastic, glass or ceramics.", "report = json.loads((PROJECT / 'data/expanded/dataset_verification.json').read_text())\nprint(json.dumps(report, indent=2))\ndisplay(pd.read_csv(PROJECT / 'data/expanded/class_counts.csv'))\nfrom IPython.display import Image, display\ndisplay(Image(filename=str(PROJECT / 'data/expanded/class_review.jpg')))"),
    ("## 6. Train the full expanded model\n\nThe training script first fits a frozen MobileNetV3Large head, then fine-tunes the last 60 backbone layers except BatchNorm with augmentation and a low learning rate. Smoothed, capped training-only class weights reduce extreme compensation. Every training image is visited each epoch, with no subset or steps-per-epoch cap. Validation macro-F1 selects checkpoints. The test partition never updates weights. Full source code is in train_full.py.", "%run train_full.py"),
    ("## 7. Inspect completed evaluation\n\nThe selected model is chosen using validation only. Compare both models on the held-out test partition. Training is complete only when the completion record exists; historical scores are not substituted for this run.", "completion = json.loads((PROJECT / 'trained_expanded/training_completed.json').read_text())\nassert completion['status'] == 'completed'\nprint(json.dumps(completion, indent=2))\ndisplay(pd.read_csv(PROJECT / 'trained_expanded/baseline_vs_finetuned.csv'))"),
]
notebook.cells = [cell for text, code in sections for cell in (nbf.v4.new_markdown_cell(text), nbf.v4.new_code_cell(code))]
nbf.write(notebook, BASE / "ECOSORT_Expanded_Training.ipynb")
